# -*- coding: utf-8 -*-
"""Independent reference times, used only for verification and reporting.

These routines are deliberately written a different way from the engine in
``ccd.core`` so that comparing the two detects implementation mistakes rather
than shared ones:

* sphere targets use the textbook quadratic written out directly;
* capsule and box targets use dense sampling followed by bisection on the
  signed distance function.

They are not part of the public collision API and never depend on it.
"""

from __future__ import annotations

import math

from .core import Box, Capsule, Sphere

__all__ = ["reference_time", "signed_distance"]

# Number of samples used before bisection.  The scan only has to bracket the
# first sign change; bisection then refines it to machine precision.
_SCAN = 4096
_BISECT = 80


def _dist_point_segment(p, a, b):
    d = (b[0] - a[0], b[1] - a[1], b[2] - a[2])
    dd = d[0] * d[0] + d[1] * d[1] + d[2] * d[2]
    if dd == 0.0:
        return math.dist(p, a)
    s = (
        (p[0] - a[0]) * d[0] + (p[1] - a[1]) * d[1] + (p[2] - a[2]) * d[2]
    ) / dd
    s = 0.0 if s < 0.0 else (1.0 if s > 1.0 else s)
    q = (a[0] + d[0] * s, a[1] + d[1] * s, a[2] + d[2] * s)
    return math.dist(p, q)


def signed_distance(p, target):
    """Signed distance from point ``p`` to the surface of ``target``."""
    if isinstance(target, Sphere):
        return math.dist(p, target.center) - target.radius
    if isinstance(target, Capsule):
        return _dist_point_segment(p, target.a, target.b) - target.radius
    if isinstance(target, Box):
        w = [p[i] - target.center[i] for i in range(3)]
        if target.rotation is None:
            q = w
        else:
            q = [
                sum(target.rotation[i][j] * w[j] for j in range(3))
                for i in range(3)
            ]
        outside = [
            max(0.0, abs(q[i]) - target.half_extents[i]) for i in range(3)
        ]
        return math.sqrt(sum(x * x for x in outside))
    raise TypeError("reference_time does not support %r" % (target,))


def reference_time(start, velocity, target, dt, radius):
    """First contact time in ``[0, dt]`` or ``None`` (reference oracle)."""
    start = tuple(float(x) for x in start)
    velocity = tuple(float(x) for x in velocity)
    dt = float(dt)
    radius = float(radius)

    def gap(t):
        p = tuple(start[i] + velocity[i] * t for i in range(3))
        return signed_distance(p, target) - radius

    if isinstance(target, Sphere):
        # Direct closed form: |w + v t|^2 = (R + r)^2.
        R = radius + target.radius
        w = tuple(start[i] - target.center[i] for i in range(3))
        a = sum(x * x for x in velocity)
        b = 2.0 * sum(w[i] * velocity[i] for i in range(3))
        c = sum(x * x for x in w) - R * R
        if c <= 0.0:
            return 0.0
        if a == 0.0:
            return None
        disc = b * b - 4.0 * a * c
        if disc < 0.0:
            return None
        t = (-b - math.sqrt(disc)) / (2.0 * a)
        if t < 0.0 or t > dt:
            return None
        return t

    if gap(0.0) <= 0.0:
        return 0.0
    if dt <= 0.0:
        return None
    step = dt / _SCAN
    prev_t = 0.0
    prev = gap(0.0)
    for k in range(1, _SCAN + 1):
        t = k * step
        cur = gap(t)
        if cur <= 0.0:
            lo, hi = prev_t, t
            for _ in range(_BISECT):
                mid = 0.5 * (lo + hi)
                if gap(mid) <= 0.0:
                    hi = mid
                else:
                    lo = mid
            return hi
        prev_t, prev = t, cur
    return None

